#include <flint/fmpq_mpoly.h>
#include <cassert>
#include <fstream>
#include <iostream>
#include <vector>
#include <string>
#include <chrono>
using namespace std;fmpq_mpoly_ctx_t ctx;
struct Poly{fmpq_mpoly_t p;Poly(){fmpq_mpoly_init(p,ctx);}Poly(const Poly&a):Poly(){fmpq_mpoly_set(p,a.p,ctx);}Poly(Poly&&a):Poly(){fmpq_mpoly_swap(p,a.p,ctx);}Poly&operator=(Poly a){fmpq_mpoly_swap(p,a.p,ctx);return *this;}~Poly(){fmpq_mpoly_clear(p,ctx);}};
void write(ostream&o,const Poly&a,int dim){fmpq_t q;fmpq_init(q);ulong ex[3];long n=fmpq_mpoly_length(a.p,ctx);o<<n;for(int i=0;i<n;i++){fmpq_mpoly_get_term_coeff_fmpq(q,a.p,i,ctx);fmpq_mpoly_get_term_exp_ui(ex,a.p,i,ctx);char*s=fmpq_get_str(nullptr,10,q);o<<' '<<s;flint_free(s);for(int j=0;j<dim;j++)o<<' '<<ex[j];}o<<'\n';fmpq_clear(q);}
int main(int argc,char**argv){assert(argc==5);ifstream in(argv[1]);ofstream out(argv[3]),lead(argv[4]);assert(in&&out&&lead);string factor=argv[2];const char*root=factor=="a"?"delta":factor=="F"?"delta+(-90*e^2-3*e+24)/500":factor=="C"?"delta+(-18*e^2+9*e+2)/100":nullptr;assert(root);fmpq_mpoly_ctx_init(ctx,3,ORD_LEX);{auto start=chrono::steady_clock::now();int nr,nc,n;in>>nr>>nc>>n;vector<vector<Poly>>A(nr,vector<Poly>(nc));fmpq_t q;fmpq_init(q);ulong ex[3];for(auto&r:A)for(auto&p:r){long nn;in>>nn;for(long z=0;z<nn;z++){string c;in>>c>>ex[0]>>ex[1]>>ex[2];assert(!fmpq_set_str(q,c.c_str(),10));fmpq_canonicalise(q);assert(fmpz_fdiv_ui(fmpq_denref(q),32003));ulong scale=1;for(ulong i=0;i<ex[2];i++)scale*=3;fmpq_mul_ui(q,q,scale);ex[2]=0;fmpq_mpoly_push_term_fmpq_ui(p.p,q,ex,ctx);}fmpq_mpoly_sort_terms(p.p,ctx);fmpq_mpoly_combine_like_terms(p.p,ctx);}int ct;in>>ct;assert(ct>=1);vector<int>rr(n),cc(n);for(int&i:rr)in>>i;for(int&i:cc)in>>i;Poly fa,ge,gz;const char*vars[]={"a","e","delta"};assert(!fmpq_mpoly_set_str_pretty(fa.p,root,vars,ctx));fmpq_mpoly_gen(ge.p,1,ctx);fmpq_mpoly_zero(gz.p,ctx);fmpq_mpoly_struct*subst[]={fa.p,ge.p,gz.p};out<<n<<' '<<n<<'\n';lead<<n<<' '<<n<<'\n';long terms=0,lterms=0;for(int i=0;i<n;i++)for(int j=0;j<n;j++){Poly p,l;assert(fmpq_mpoly_compose_fmpq_mpoly(p.p,A[rr[i]][cc[j]].p,subst,ctx,ctx));write(out,p,3);terms+=fmpq_mpoly_length(p.p,ctx);for(int k=0;k<fmpq_mpoly_length(p.p,ctx);k++){fmpq_mpoly_get_term_exp_ui(ex,p.p,k,ctx);assert(ex[0]==0);if(ex[2])continue;fmpq_mpoly_get_term_coeff_fmpq(q,p.p,k,ctx);fmpq_mpoly_push_term_fmpq_ui(l.p,q,ex,ctx);}fmpq_mpoly_sort_terms(l.p,ctx);lterms+=fmpq_mpoly_length(l.p,ctx);write(lead,l,2);}out.flush();lead.flush();assert(out.good()&&lead.good());cerr<<"EXPORT_PASS "<<factor<<" TERMS "<<terms<<" LEADING "<<lterms<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';fmpq_clear(q);}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
